import{_ as r,c as l,o as e,ag as t}from"./chunks/framework.Bkod66qp.js";const u=JSON.parse('{"title":"임시기구 운영내규","description":"","frontmatter":{"title":"임시기구 운영내규","subtitle":"","doc_id":"","last_update":"2025-02-06","author":"","categories":[],"tags":[]},"headers":[],"relativePath":"regulation/202_임시기구 운영내규(250206).md","filePath":"regulation/202_임시기구 운영내규(250206).md"}'),o={name:"regulation/202_임시기구 운영내규(250206).md"};function i(s,a,n,c,h,d){return e(),l("div",null,a[0]||(a[0]=[t('<h1 id="law-title" class="center" tabindex="-1">임시기구 운영내규 <a class="header-anchor" href="#law-title" aria-label="Permalink to &quot;임시기구 운영내규 {#law-title .center}&quot;">​</a></h1><div style="text-align:right;"><pre style="display:inline-block;margin:0;white-space:pre;font-family:monospace;">제정 2025.   2.   6</pre></div><h2 id="article1" class="sr-only" tabindex="-1">제1조 (목적) <a class="header-anchor" href="#article1" aria-label="Permalink to &quot;제1조 (목적) {#article1 .sr-only}&quot;">​</a></h2><p><strong>제1조(목적)</strong> 이 내규는 서울문화재단(이하 “재단”이라 한다.) 직제규정 제3조에 따른 임시기구 설치 운영에 필요한 사항을 규정함을 목적으로 한다.</p><h2 id="article2" class="sr-only" tabindex="-1">제2조 (정의) <a class="header-anchor" href="#article2" aria-label="Permalink to &quot;제2조 (정의) {#article2 .sr-only}&quot;">​</a></h2><p><strong>제2조(정의)</strong> 이 내규에서 사용하는 용어의 정의는 다음과 같다.</p><ol><li>“임시기구”는 특정업무 또는 한시업무를 수행하기 위해 직제규정으로 정한 조직 외에 설치한 조직을 말한다. 2. “조직관리 부서”는 재단의 조직과 정원에 관한 사항을 총괄하는 부서를 말한다.</li><li>“겸직”은 직원이 현재 직위 이외의 직위 또는 직무를 수행하는 것을 말한다.</li><li>“전임”은 직원이 현재 직위 또는 직무만을 수행하는 것을 말한다.</li></ol><h2 id="article3" class="sr-only" tabindex="-1">제3조 (임무) <a class="header-anchor" href="#article3" aria-label="Permalink to &quot;제3조 (임무) {#article3 .sr-only}&quot;">​</a></h2><p><strong>제3조(임무)</strong> 임시기구는 다음 각 호의 어느 하나에 해당하는 업무를 위한 정책 개발, 제도 개선방안 도출, 사업 기획 및 실행 등의 임무를 수행한다.</p><ol><li>특정업무 : 업무의 특수성과 효율성 등을 고려해 직제규정상의 조직으로는 사업목적 달성 또는 수행이 곤란한 업무 2. 한시업무 : 단기간에 해결이 필요한 현안으로 독립적 수행이 필요한 업무</li></ol><h2 id="article4" class="sr-only" tabindex="-1">제4조 (인력배치) <a class="header-anchor" href="#article4" aria-label="Permalink to &quot;제4조 (인력배치) {#article4 .sr-only}&quot;">​</a></h2><p><strong>제4조(인력배치)</strong> ① 대표이사는 임시기구의 효율적인 운영을 위해 부서장과 부서원을 둘 수 있으며, 인력 규모는 수행업무에 따른다.<br> ② 부서장은 임시기구가 수행해야 하는 업무에 전문성과 경험을 가진 재단 직원을 겸직시킬 수 있다.<br> ③ 부서원은 전임 직원을 신규 채용하거나, 관련 분야에 전문성을 갖춘 재단 직원 중 대표이사가 임명하되 다른 업무와 겸직시킬 수 있다.</p><h2 id="article5" class="sr-only" tabindex="-1">제5조 (운영기간) <a class="header-anchor" href="#article5" aria-label="Permalink to &quot;제5조 (운영기간) {#article5 .sr-only}&quot;">​</a></h2><p><strong>제5조(운영기간)</strong> 임시기구의 운영기간은 1년 이내를 원칙으로 하되, 다음 각 호의 경우 1회에 한하여 기한을 정해 연장할 수 있다.</p><ol><li>외부환경 여건 변화에 따라 사업목적 달성시기와 존속기간이 변동되는 경우</li><li>사업목적 달성을 위해 지속적인 노력이 필요한 경우</li></ol><h2 id="article6" class="sr-only" tabindex="-1">제6조 (보상) <a class="header-anchor" href="#article6" aria-label="Permalink to &quot;제6조 (보상) {#article6 .sr-only}&quot;">​</a></h2><p><strong>제6조(보상)</strong> 임시기구 설치 시 운영목적 달성 등 구성원의 목표달성에 따른 보상방안 또는 보상제도를 검토하여 운영계획에 반영하여야 한다.</p><h2 id="article7" class="sr-only" tabindex="-1">제7조 (운영계획 제출) <a class="header-anchor" href="#article7" aria-label="Permalink to &quot;제7조 (운영계획 제출) {#article7 .sr-only}&quot;">​</a></h2><p><strong>제7조(운영계획 제출)</strong> ① 임시기구 부서장은 임시기구 설치와 인력 배치가 완료되면 운영계획을 수립하여 조직관리 부서장을 경유하여 대표이사의 승인을 득하여야 한다.<br> ② 운영계획에는 임시기구의 설치목적, 운영기간, 인력구성, 주요사업 기본계획, 구성원 보상방안 검토결과 등을 명기하여야 한다.</p><h2 id="article8" class="sr-only" tabindex="-1">제8조 (운영계획 변경) <a class="header-anchor" href="#article8" aria-label="Permalink to &quot;제8조 (운영계획 변경) {#article8 .sr-only}&quot;">​</a></h2><p><strong>제8조(운영계획 변경)</strong> ① 임시기구 부서장은 운영계획의 변경이 필요한 경우, 그동안의 추진실적, 변경사유 등을 작성하여 조직관리 부서장을 경유하여 대표이사에게 보고하여야 한다.<br> ② 운영계획 변경은 경영환경 변화 등으로 불가피하게 사업목적 달성에 차질이 발생하는 경우 또는 사업목적 달성을 위해 지속적인 노력이 요구되는 경우로 제한한다.</p><h2 id="article9" class="sr-only" tabindex="-1">제9조 (해산 등) <a class="header-anchor" href="#article9" aria-label="Permalink to &quot;제9조 (해산 등) {#article9 .sr-only}&quot;">​</a></h2><p><strong>제9조(해산 등)</strong> ① 임시기구는 다음 각 호의 사유가 발생하면 대표이사에게 임시기구 운영결과를 보고한 후 결재를 받아 해산한다.</p><ol><li>임시기구의 운영기간이 종료된 경우</li><li>임시기구의 사업목표가 상실되거나 달성된 경우</li><li>그 밖에 업무추진 실적 미진, 목표달성 곤란 등 경영정책상 해산이 필요한 경우<br> ② 임시기구 부서장은 임시기구의 해산 예정일까지 조직관리 부서장을 경유하여 해산사유 및 일자, 사업추진 실적 및 성과, 후속조치 등을 대표이사에게 보고하여야 한다.</li></ol><h2 id="article10" class="sr-only" tabindex="-1">제10조 (인수인계) <a class="header-anchor" href="#article10" aria-label="Permalink to &quot;제10조 (인수인계) {#article10 .sr-only}&quot;">​</a></h2><p><strong>제10조(인수인계)</strong> 임시기구의 운영 중 생산된 서류와 각종 자료 일체는 업무분장, 사업의 연속성 등을 고려하여 임시기구 해산 전까지 인수 부서에 인계하여야 한다.</p><h2 id="article11" class="sr-only" tabindex="-1">제11조 (정규조직 전환) <a class="header-anchor" href="#article11" aria-label="Permalink to &quot;제11조 (정규조직 전환) {#article11 .sr-only}&quot;">​</a></h2><p><strong>제11조(정규조직 전환)</strong> ① 대표이사는 임시기구가 다음 각 호의 어느 하나에 해당하는 경우 정규조직으로 전환할 수 있다.</p><ol><li>경영 관련 중요 현안의 해결 또는 프로젝트 추진을 위해 다년간(2년 이상)의 시간이 소요되는 경우</li><li>경영환경 변화 등에 따라 임시기구 설치목적이 재단의 전략목표로 확대되거나, 향후 지속적으로 추구해야 할 주요업무로 인정되는 경우</li><li>기타 대표이사가 필요하다고 인정하는 경우<br> ② 대표이사는 임시기구를 정규조직으로 전환하는 경우 이에 관한 사항을 이사회에 보고하여야 한다.</li></ol><h2 id="article12" class="sr-only" tabindex="-1">제12조 (경과 보고) <a class="header-anchor" href="#article12" aria-label="Permalink to &quot;제12조 (경과 보고) {#article12 .sr-only}&quot;">​</a></h2><p><strong>제12조(경과 보고)</strong> 대표이사는 임시기구를 설치하거나 해산하는 경우 이에 관한 사항을 이사회에 보고하여야 한다.</p><h2 id="article13" class="sr-only" tabindex="-1">제13조 (운영재원) <a class="header-anchor" href="#article13" aria-label="Permalink to &quot;제13조 (운영재원) {#article13 .sr-only}&quot;">​</a></h2><p><strong>제13조(운영재원)</strong> 임시기구의 운영에 필요한 경비는 재단의 운영예산으로 충당한다.</p><h2 id="article14" class="sr-only" tabindex="-1">제14조 (보칙) <a class="header-anchor" href="#article14" aria-label="Permalink to &quot;제14조 (보칙) {#article14 .sr-only}&quot;">​</a></h2><p><strong>제14조(보칙)</strong> 이 내규에서 정하지 않은 사항은 재단의 제규정을 따른다.</p><h2 id="addendum1" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum1" aria-label="Permalink to &quot;부칙 {#addendum1 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong><br> 제1조(시행일) 이 내규는 대표이사의 승인을 받은 날로부터 시행한다.<br> 제2조(경과조치) 이 내규 시행 전에 대표이사의 방침을 받아 설치된 임시기구는 이 내규에 의하여 시행된 것으로 본다.</p>',37)]))}const b=r(o,[["render",i]]);export{u as __pageData,b as default};
